from taf.analyzer.aasyslog_throughput.throughput_data import (ThroughputData,
                                                              ThroughputResult,
                                                              FixedDevicesThroughputDataCollection)


class CellThroughputResult(ThroughputResult):
    @property
    def device_id_key_name(self):
        return "cellid"

    def to_dict(self):
        return {self.device_id_key_name: self.device_id, 'peak': self.peak, 'average': self.average,
                'minimum': self.minimum, 'count': self.count,
                'min_time_interval': self.min_time_interval}


class CellThroughputData(ThroughputData):
    def __init__(self, device_id):
        super(CellThroughputData, self).__init__(device_id)
        self._result = CellThroughputResult(device_id)

    @classmethod
    def create(cls, device_id, throughput_value=None, timestamp=None, **kwargs):
        cell_data = CellThroughputData(device_id)
        if throughput_value:
            cell_data.current = throughput_value
        if timestamp:
            cell_data.utc_time = timestamp

        return cell_data

    @property
    def cell_id(self):
        return self._device_id

    def __str__(self):
        return str({"cell_id": self.cell_id, 'current': self.current, 'result': self._result})


class CAFixedCellsThroughputDataCollection(FixedDevicesThroughputDataCollection):
    def __init__(self, device_ids):
        super(CAFixedCellsThroughputDataCollection, self).__init__(device_ids=device_ids,
                                                                   throughput_data_factory=CellThroughputData)
        self._result = CellThroughputResult()

    @property
    def result(self):
        return self._result

    def reset(self):
        super(CAFixedCellsThroughputDataCollection, self).reset()
        self._result.reset()

    def update_min_time_interval(self, throughput_data, value):
        super(CAFixedCellsThroughputDataCollection, self).update_min_time_interval(throughput_data, value)
        self._result.min_time_interval = super(CAFixedCellsThroughputDataCollection, self).min_time_interval
